using LWS.TruckSports.Editor;
namespace LWS.TruckJenga.Editor
{
    public static class JengaAuthoring
    {
        public const string Folder="TruckJenga",Scene="Assets/TruckJenga/Scenes/TruckJenga.unity";
        public static readonly string[] Containers={"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab","Assets/ShipContainerPack/URP/Prefabs/ShipContainerGray_URP.prefab","Assets/ShipContainerPack/URP/Prefabs/ShipContainerBlue_URP.prefab"};
        const string Human="Assets/LWS/TruckTaxi/Passengers/Animations/Humanoid/";
        [MenuItem("Truck Sports/Alpha 0.7/Create NEW Truck Jenga")]
        public static void CreateNewScene(){if(File.Exists(Scene))throw new InvalidOperationException("New-scene author refuses to overwrite "+Scene);var match=SportsEventAuthoring.Begin<JengaMatch>(Folder);match.setup.count=2;match.NormalizeSetup();match.feedback.clips=Audio();Install(match);SportsEventAuthoring.UI(match);Controls(match);match.drivingViews=SportsDrivingViewsAuthoring.Install(match,match.trucks,match.broadcast,Folder);match.drivingViews.independentViewModes=true;SportsEventAuthoring.Save(Folder);Debug.Log("JENGA_NEW_SCENE 18 actual dynamic ShipContainerPack containers, full NWH, existing Tug rope, physical crane. Shared NEW-scene bindings remain lead-owned.");}
        public static void Install(JengaMatch match)
        {
            if(EditorApplication.isPlaying||EditorApplication.isCompiling||match==null||(!string.IsNullOrEmpty(match.gameObject.scene.path)&&match.gameObject.scene.path!=Scene)||match.transform.Find("Working industrial container port")!=null)throw new InvalidOperationException("Install needs a new unauthored Jenga authority.");var root=new GameObject("Working industrial container port").transform;root.SetParent(match.transform,false);
            var concrete=SportsEventAuthoring.Mat(Folder,"Worn port concrete",new Color(.36f,.38f,.39f),.14f);var physical=SportsEventAuthoring.Contact(Folder,"Port wheel contact",.7f,.01f);SportsEventAuthoring.Box("One continuous physical dock deck",new Vector3(0,-.7f,0),new Vector3(110,1.4f,110),concrete,physical,root);
            for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)Prop(root,"Assets/Hivemind/ModularWarehouse/URP/Art/Prefabs/SM_Floor_Concrete_600_A.prefab",new Vector3(x*15,.012f,z*15),new Vector3(15,.08f,15));
            var material=SportsEventAuthoring.Contact(Folder,"Container steel sliding contact",.11f,0);material.frictionCombine=PhysicsMaterialCombine.Minimum;
            match.containers=new Rigidbody[18];match.shapes=new BoxCollider[18];for(int i=0;i<18;i++){
                var piece=new GameObject("Actual dynamic Jenga container "+(i+1));piece.transform.SetParent(root,false);var visual=Visual(Containers[i%3],piece.transform);FitCentered(visual,match.pieceSize);var box=piece.AddComponent<BoxCollider>();box.size=new Vector3(match.pieceSize.x-.025f,match.pieceSize.y,match.pieceSize.z-.025f);box.contactOffset=.005f;box.sharedMaterial=material;var body=piece.AddComponent<Rigidbody>();body.mass=180;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.linearDamping=.06f;body.angularDamping=.12f;body.solverIterations=36;body.solverVelocityIterations=16;body.maxDepenetrationVelocity=2;body.maxLinearVelocity=25;piece.transform.SetPositionAndRotation(match.Slot(i/3,i%3),match.Rotation(i/3));match.containers[i]=body;match.shapes[i]=box;
                var number=SportsEventAuthoring.Label("Real container number",(i+1).ToString("00"),Vector3.zero,.23f,Color.white);number.transform.SetParent(piece.transform,false);number.transform.localPosition=new Vector3(0,.15f,-match.pieceSize.z*.5f-.03f);
            }
            // Editor Rigidbody pose caches need not follow a just-authored Transform before simulation.
            // Persist the intended world-space slots, never the stale native Rigidbody cache.
            match.initialPositions=Enumerable.Range(0,18).Select(i=>match.Slot(i/3,i%3)).ToArray();match.initialRotations=Enumerable.Range(0,18).Select(i=>match.Rotation(i/3)).ToArray();
            for(int i=0;i<18;i++){match.containers[i].position=match.initialPositions[i];match.containers[i].rotation=match.initialRotations[i];}
            JengaResetPoseRepair.ValidateOriginalTower(match);
            match.trucks=new SportsEventTruck[4];for(int i=0;i<4;i++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(LWS.TruckFareFight.Editor.FareFightVehicleAuthoring.PrefabPath);if(prefab==null)throw new InvalidOperationException("Existing full NWH Fare Fight tractor required; no prefab regeneration.");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.name="Jenga full NWH fixed owner "+i;g.transform.position=new Vector3(-25+i*7,.7f,-27);var truck=g.GetComponent<SportsEventTruck>();if(truck==null||truck.tractorMotor==null)throw new InvalidOperationException("Full original NWH facade required.");truck.session=match;truck.slot=i;truck.tractorMotor.settings=match.settings;match.trucks[i]=truck;EditorUtility.SetDirty(truck);EditorUtility.SetDirty(truck.tractorMotor);}
            var yellow=SportsEventAuthoring.Mat(Folder,"Crane safety enamel",new Color(.96f,.56f,.07f),.5f);var steel=SportsEventAuthoring.Mat(Folder,"Gantry brushed steel",new Color(.22f,.3f,.34f),.7f);steel.SetFloat("_Metallic",.75f);var rubber=SportsEventAuthoring.Mat(Folder,"Braided crane cable",new Color(.09f,.1f,.11f),.2f);
            match.winch=match.gameObject.AddComponent<JengaWinch>();match.winch.cable=Line("Original physical winch cable",rubber,.07f,root);
            match.crane=match.gameObject.AddComponent<JengaCrane>();match.crane.ceiling=48;
            var gantry=new GameObject("Purpose-built moving container crane").transform;gantry.SetParent(root,false);
            for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2){Prop(gantry,"Assets/ScaffoldsPack/URP/Prefabs/SM_StairTower.prefab",new Vector3(x*21,0,z*22),new Vector3(4,48,4));Beam(gantry,new Vector3(x*21,0,z*22),new Vector3(x*21,48,z*22),.45f,steel,"Structural gantry column");}
            for(int z=-1;z<=1;z+=2)Beam(gantry,new Vector3(-24,48,z*22),new Vector3(24,48,z*22),.5f,yellow,"Actual longitudinal crane rail");
            var bridge=new GameObject("Motorized crane bridge").transform;bridge.SetParent(gantry,false);bridge.position=new Vector3(16,48,0);match.crane.bridge=bridge;Beam(bridge,new Vector3(0,0,-23),new Vector3(0,0,23),.35f,yellow,"Moving bridge girder");
            var trolley=new GameObject("Moving cable reel trolley").transform;trolley.SetParent(gantry,false);match.crane.trolley=trolley;Prop(trolley,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_CableReel01 Variant.prefab",Vector3.zero,new Vector3(3,2.2f,3));
            var spreader=new GameObject("Physically connected motor-driven crane spreader");spreader.transform.SetParent(gantry,false);spreader.transform.position=new Vector3(16,22,0);var motor=spreader.AddComponent<Rigidbody>();motor.isKinematic=true;motor.useGravity=false;motor.interpolation=RigidbodyInterpolation.Interpolate;match.crane.spreader=motor;
            for(int side=-1;side<=1;side+=2){Beam(spreader.transform,new Vector3(side*1.3f,0,-4),new Vector3(side*1.3f,0,4),.13f,yellow,"Actual spreader beam");Beam(spreader.transform,new Vector3(-1.3f,0,side*4),new Vector3(1.3f,0,side*4),.13f,yellow,"Actual locking spreader end");}
            match.crane.hoist=Line("Visible motor crane hoist",rubber,.08f,gantry);match.crane.hoist.positionCount=2;
            var marker=new GameObject("Legal selected physical container outline").transform;marker.SetParent(root,false);match.selectionMarker=marker;for(int y=-1;y<=1;y+=2)for(int x=-1;x<=1;x+=2)Beam(marker,new Vector3(x*1.68f,y*1.25f,-4.86f),new Vector3(x*1.68f,y*1.25f,4.86f),.045f,yellow,"Readable selection rail");
            for(int i=0;i<12;i++){float a=i*Mathf.PI/6;Vector3 p=new Vector3(Mathf.Sin(a)*12,.025f,Mathf.Cos(a)*12);var arrow=SportsEventAuthoring.Box("Marked winch staging perimeter",p,new Vector3(.6f,.03f,1.8f),yellow,null,root);arrow.transform.rotation=Quaternion.Euler(0,a*Mathf.Rad2Deg,0);}
            for(int side=-1;side<=1;side+=2){Prop(root,"Assets/JC_LP_MegaCity/Prefabs/Buildings/SM_Buildings_Warehouse_01.prefab",new Vector3(side*41,0,35),new Vector3(31,19,28));for(int n=0;n<8;n++){var cargo=Visual(Containers[n%3],root);FitCentered(cargo,new Vector3(3,2.5f,9));cargo.transform.position=new Vector3(side*43,1.25f+(n/4)*2.5f,-35+(n%4)*11);}}
            foreach(var p in new[]{new Vector3(-38,0,-44),new Vector3(35,0,-44),new Vector3(27,0,39)}){Prop(root,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_BoxesPack01 Variant.prefab",p,new Vector3(5,4,5));Prop(root,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab",p+Vector3.right*5,new Vector3(4,.6f,4));}
            var water=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckDockDiving/Materials/Pool water.mat");if(water==null)throw new InvalidOperationException("Existing owned water material required.");SportsEventAuthoring.Box("Harbor water beyond the solid dock",new Vector3(0,-1.2f,100),new Vector3(350,.15f,90),water,null,root);
            match.spectators=Crowd(root);match.broadcast=SportsEventAuthoring.Camera("Jenga original Cinemachine broadcast");match.cameras=new[]{match.broadcast.view};match.broadcast.Pose(Vector3.up*6,new Vector3(24,20,-30),58,true);
        }
        static GameObject Visual(string path,Transform parent){var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(source==null)throw new InvalidOperationException("Owned visual required: "+path);var instance=(GameObject)PrefabUtility.InstantiatePrefab(source);instance.transform.SetParent(parent,false);foreach(var behaviour in instance.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(behaviour);foreach(var body in instance.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(body);foreach(var collider in instance.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);return instance;}
        static Bounds BoundsOf(GameObject model){var renderers=model.GetComponentsInChildren<Renderer>(true);if(renderers.Length==0)throw new InvalidOperationException("Real render geometry required: "+model.name);Bounds b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);return b;}
        static void FitCentered(GameObject model,Vector3 size){var b=BoundsOf(model);if(b.size.x<.001f||b.size.y<.001f||b.size.z<.001f)throw new InvalidOperationException("Container needs finite positive real render bounds.");if(b.size.x>b.size.z){model.transform.localRotation=Quaternion.Euler(0,90,0);b=BoundsOf(model);}model.transform.localScale=Vector3.Scale(model.transform.localScale,new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z));b=BoundsOf(model);model.transform.position+=model.transform.parent.position-b.center;}
        static void Prop(Transform parent,string path,Vector3 position,Vector3 size){var holder=new GameObject("Owned port prop · "+Path.GetFileNameWithoutExtension(path)).transform;holder.SetParent(parent,false);var model=Visual(path,holder);var b=BoundsOf(model);model.transform.localScale=Vector3.Scale(model.transform.localScale,new Vector3(size.x/Mathf.Max(.001f,b.size.x),size.y/Mathf.Max(.001f,b.size.y),size.z/Mathf.Max(.001f,b.size.z)));b=BoundsOf(model);model.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z)-holder.position;holder.localPosition=position;}
        static void Beam(Transform parent,Vector3 a,Vector3 b,float r,Material material,string name){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);g.transform.localScale=new Vector3(r*2,(b-a).magnitude*.5f,r*2);g.GetComponent<Renderer>().sharedMaterial=material;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
        static LineRenderer Line(string name,Material material,float width,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);var line=g.AddComponent<LineRenderer>();line.sharedMaterial=material;line.startWidth=line.endWidth=width;line.useWorldSpace=true;line.positionCount=2;return line;}
        static AudioClip[] Audio(){string[] paths={"Assets/Heat - Complete Modern UI/Audio/Click.wav","Assets/TruckBilliards/Audio/Ball.wav","Assets/NWH/Vehicle Physics 2/Sound/Transmission/Gear1.wav","Assets/TruckBilliards/Audio/Strike.wav","Assets/TruckDockDiving/Audio/Ordinary applause.wav","Assets/TruckHockey/Audio/GoalHorn.wav","Assets/TruckHockey/Audio/FinalWhistle.wav"};return paths.Select(path=>{var c=AssetDatabase.LoadAssetAtPath<AudioClip>(path);if(c==null)throw new InvalidOperationException("Existing audio required: "+path);return c;}).ToArray();}
        static Animator[] Crowd(Transform root)
        {
            string path="Assets/TruckJenga/Materials/Port crowd.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(controller==null)controller=AnimatorController.CreateAnimatorControllerAtPath(path);foreach(var pair in new[]{("Idle","idle1"),("Cheer","cheer"),("Shout","shout")}){var machine=controller.layers[0].stateMachine;var state=machine.states.FirstOrDefault(s=>s.state.name==pair.Item1).state;if(state==null)state=machine.AddState(pair.Item1);if(state.motion==null)state.motion=AssetDatabase.LoadAllAssetsAtPath(Human+pair.Item2+".FBX").OfType<AnimationClip>().First(c=>c.humanMotion&&!c.name.StartsWith("__"));if(pair.Item1=="Idle")machine.defaultState=state;EditorUtility.SetDirty(state);EditorUtility.SetDirty(machine);}EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();var result=new List<Animator>();for(int i=0;i<16;i++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Human+(i%2==0?"business01_m":"business01_f")+".FBX");if(prefab==null)throw new InvalidOperationException("Genuine Taxi humanoid render model required.");var person=UnityEngine.Object.Instantiate(prefab,root);person.name="Genuine port spectator "+i;var actor=person.GetComponent<Animator>();if(actor==null||actor.avatar==null||!actor.avatar.isHuman)throw new InvalidOperationException("Genuine Human avatar required.");actor.runtimeAnimatorController=controller;actor.applyRootMotion=false;actor.cullingMode=AnimatorCullingMode.AlwaysAnimate;person.transform.localPosition=new Vector3(-24+i*3.2f,0,-39);person.transform.localScale=Vector3.one*2;result.Add(actor);}for(int i=0;i<7;i++)Prop(root,"Assets/JC_LP_MegaCity/Prefabs/FloorProps/SM_FloorProps_Fence_01.prefab",new Vector3(-24+i*8,0,-35),new Vector3(8,2,1));return result.ToArray();
        }
        static void Controls(JengaMatch match){var parent=match.menus.hud.transform;string[] names={"PREVIOUS PIECE","NEXT PIECE","PULLING END","ATTACH / BEGIN","RELEASE CABLE"},keys={"jenga.previous","jenga.next","jenga.end","jenga.attach","jenga.release"};match.selectionControls=new GameObject[3];for(int i=0;i<5;i++){var button=SportsUIAuthoring.Button(parent,names[i],keys[i],new Vector2(-680+i*340,-425),new Vector2(320,48));if(i<3)match.selectionControls[i]=button.gameObject;else if(i==3)match.attachControl=button.gameObject;else match.releaseControl=button.gameObject;}}
    }
